class Solution {
public:
    long long repairCars(vector<int>& ranks, int cars) {
        long long lo = 1;
        long long hi = 100LL * (long long)cars * cars;
        while (lo < hi) {
            long long mid = lo + (hi - lo) / 2;
            long long total = 0;
            for (int r : ranks) {
                long long c = (long long)sqrtl((long double)mid / r);
                while ((c + 1) * (c + 1) <= mid / r) c++;
                while (c > 0 && c * c > mid / r) c--;
                total += c;
                if (total >= cars) break;
            }
            if (total >= cars) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};
